import { writeFileSync, readFileSync } from 'node:fs';
import { vectorTypes, vectorInfo } from '../engine/numeric-types.js';

// Emit source, rather than building closures or decoding selectors at runtime.
const lines = [
  '// Generated by node scripts/generate-swizzles.mjs. Do not edit by hand.',
  "import { numericFromComponents } from './data.js';",
  '',
  'export const swizzleAccessors = Object.assign(Object.create(null), {',
];
for (const type of vectorTypes) {
  const { size, scalar, suffix } = vectorInfo(type);
  const letters = 'xyzw'.slice(0, size);
  lines.push(`  ${type}: Object.assign(Object.create(null), {`);
  let names = [''];
  for (let length = 1; length <= 4; length++) {
    names = names.flatMap(prefix => [...letters].map(letter => prefix + letter));
    for (const name of names) {
      const indices = [...name].map(letter => 'xyzw'.indexOf(letter));
      const components = indices.map(index => `v.values[${index}]`).join(', ');
      const resultType = length === 1 ? scalar : `vec${length}${suffix}`;
      const read = length === 1 ? components : `numericFromComponents('${resultType}', [${components}])`;
      const write = new Set(name).size === length
        ? `, write: (v, values) => { ${indices.map((index, i) => `v.values[${index}] = values[${i}];`).join(' ')} }`
        : '';
      lines.push(`    ${name}: { read: v => ${read}, replacementType: '${resultType}'${write} },`);
    }
  }
  lines.push('  }),');
}
lines.push('});', '',
  'export const swizzleNames = new Set(Object.keys(swizzleAccessors.vec4f));',
  'export const writableSwizzleNames = new Set(Object.keys(swizzleAccessors.vec4f).filter(name => swizzleAccessors.vec4f[name].write));', '');
const source = lines.join('\n');
const destination = new URL('../engine/swizzles.generated.js', import.meta.url);
if (process.argv.includes('--check')) {
  if (readFileSync(destination, 'utf8').replace(/\r\n/g, '\n') !== source) {
    throw new Error('Generated swizzles are stale; run node scripts/generate-swizzles.mjs');
  }
} else {
  writeFileSync(destination, source);
}
